def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    out = [[bg for _ in range(w)] for _ in range(h)]
    for color in counts:
        if color == bg:
            continue
        pref = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            for c in range(w):
                pref[r+1][c+1] = pref[r][c+1] + pref[r+1][c] - pref[r][c] + (grid[r][c] == color)
        for r0 in range(h):
            for r1 in range(r0 + 2, h + 1):
                for c0 in range(w):
                    for c1 in range(c0 + 2, w + 1):
                        area = (r1-r0) * (c1-c0)
                        n = pref[r1][c1] - pref[r0][c1] - pref[r1][c0] + pref[r0][c0]
                        if n / area <= 0.70:
                            continue
                        if any(pref[r+1][c1]-pref[r][c1]-pref[r+1][c0]+pref[r][c0] == 0 for r in range(r0,r1)):
                            continue
                        if any(pref[r1][c+1]-pref[r0][c+1]-pref[r1][c]+pref[r0][c] == 0 for c in range(c0,c1)):
                            continue
                        for r in range(r0,r1):
                            for c in range(c0,c1):
                                out[r][c] = color
    return out

