    counts=Counter(v for row in g for v in row)
    bg=counts.most_common(1)[0][0]
    seen=set(); retained=set()
    for r in range(h):
        for c in range(w):
            color=g[r][c]
            if (r,c) in seen: continue
            q=[(r,c)];seen.add((r,c)); size=0
            for x,y in q:
                size+=1
                for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=a<h and 0<=b<w and (a,b) not in seen and g[a][b]==color:
                        seen.add((a,b));q.append((a,b))
            if color != bg and size>=4:
                retained.add(color)
